function mpc = npcc_nygrid_2025_downstate_dc(hour_index, variant, artifact_folder)
%NPCC_NYGRID_2025_DOWNSTATE_DC Expanded full-NPCC fixed-dispatch DC research case.
% Default: dated2025 topology with the frozen baseline injection landings.
% Asset mapping variants are diagnostic, pending load/flowgate qualification.
% Public station/project facts and assumed impedances are in the registers.
% Neither AC feasibility nor physical2025 flowgate membership is certified.
if nargin < 1, hour_index = 1; end
if nargin < 2 || isempty(variant), variant = 'upgrades_dated'; end
root = fileparts(fileparts(mfilename('fullpath')));
if nargin < 3 || isempty(artifact_folder)
    artifact_folder = fullfile(root, 'output', 'nygrid_2025_downstate');
end
allowed = {'expanded_identity', 'source_detail_2019', 'upgrades_year_end', ...
    'upgrades_dated', 'assets_year_end', 'assets_dated', 'nyes_assumption_year_end'};
assert(any(strcmp(variant, allowed)), 'nygridDownstate:Variant', 'Unknown refinement variant.');
% This loader enforces the source cohort and restores the frozen hourly PG,
% PMIN/PMAX, DC schedules and reference policy before applying network changes.
mpc = npcc_nygrid_2025_full_dc(hour_index);

function mpc = npcc_nygrid_2025_slim_dc(hour_index, variant, artifact_folder)
%NPCC_NYGRID_2025_SLIM_DC Full NPCC plus eight critical345kV transmission buses.
% All140 original buses remain. Only43 zero-injection added buses from the
% detailed reference are eliminated. Equivalent branches are DC response
% representations and have no certified conductor, thermal rating or AC model.
% Use npcc_nygrid_2025_slim_interfaces(result) after a successful rundcpf to
% recover the same seven interface functionals as the191bus reference.
if nargin<1, hour_index=1; end
if nargin<2 || isempty(variant), variant='topology_dated'; end
root=fileparts(fileparts(mfilename('fullpath')));
if nargin<3 || isempty(artifact_folder)
    artifact_folder=fullfile(root,'output','nygrid_2025_slim');
end
assert(any(strcmp(variant,{'topology_dated','topology_year_end'})), ...
    'nygridSlim:Variant','Choose topology_dated or topology_year_end. Asset-remapping diagnostics are not supported.');
% Reuse frozen source qualification, per-generatorPG/bounds, signedDC schedules.
mpc=npcc_nygrid_2025_full_dc(hour_index);
reference=mpc.bus(mpc.bus(:,2)==3,1);

function mpc = npcc_nygrid_2025_moses_corrected_dc(hour_index, control, topology)
%NPCC_NYGRID_2025_MOSES_CORRECTED_DC Versioned source-backed allocation repair.
% The frozen148bus topology, generator outputs/bounds, loads and regional
% exchanges remain. Plant-specific Gold Book evidence corrects generator bus
% assignments. Any enabled PAR target must come from an independently verified
% source, never from a scored Moses South observation.
if nargin<1, hour_index=1; end
if nargin<2 || isempty(control), control='hydro_zone_corrected'; end
if nargin<3 || isempty(topology), topology='dated'; end
assert(any(strcmp(topology,{'dated','year_end'})), ...
    'mosesCorrection:Topology','Choose dated or year_end.');
assert(strcmp(control,'hydro_zone_corrected'), ...
    'mosesCorrection:Control','Only the confirmed hydro-zone repair is promoted. PAR orientation diagnostics are not operational cases.');
mpc=npcc_nygrid_2025_slim_dc(hour_index,['topology_',char(topology)]);
root=fileparts(fileparts(mfilename('fullpath')));
file=fullfile(root,'output','nygrid_2025_moses_audit','replay', ...
    [char(topology),'_',char(control),'.mat']);
assert(isfile(file),'mosesCorrection:MissingReplay','Build and validate this corrected variant first.');

function mpc = npcc_nygrid_2025_par_controlled_dc(hour_index, topology)
%NPCC_NYGRID_2025_PAR_CONTROLLED_DC Direction-verified external PAR-flow replay.
% Two ideal lossless PAR transfer equivalents use the dcline container. They
% are NOT new physical HVDC links or a simulation of measured physical taps.
% The original branch211 stays as a provenance record, inactive only because
% its transfer is represented by the two source-identified controlled ports.
% Each input passes the nominal300MVA-derived |P| screen. UnknownQ, actual tap
% states and emergency envelopes prevent complete hardware-feasibility claims.
if nargin<1, hour_index=1; end
if nargin<2 || isempty(topology), topology='dated'; end
assert(any(strcmp(topology,{'dated','year_end'})), ...
    'nygridPAR:Topology','Choose dated or year_end.');
mpc=npcc_nygrid_2025_moses_corrected_dc(hour_index,'hydro_zone_corrected',topology);
root=fileparts(fileparts(mfilename('fullpath')));
file=fullfile(root,'output','nygrid_2025_par_controls','replay', ...
    [char(topology),'_verified_PAR_flows.mat']);
assert(isfile(file),'nygridPAR:MissingArtifact','Build and validate the source-controlled replay first.');
persistent cached_file cached_signature r

function mpc = npcc_nygrid_2025_western_corrected_dc(hour_index, topology, mode)
%NPCC_NYGRID_2025_WESTERN_CORRECTED_DC Source-corrected western DC reconstruction.
% Default combined: corrected generator locations and NYIS-reported physical
% exchanges for all four neighboring regions, with the frozen bounded source-
% prior generation projection. Individual units are reconstructed, not observed.
% Ontario-only modes retain schedules elsewhere and are diagnostic scenarios.
% Original four DC-device schedules and external P34 PAR targets are retained.
if nargin<1, hour_index=1; end
if nargin<2 || isempty(topology), topology='dated'; end
if nargin<3 || isempty(mode), mode='combined'; end
assert(any(strcmp(topology,{'dated','year_end'})), ...
    'westernCorrection:Topology','Choose dated or year_end.');
modes={'mapping_only','Ontario_actual_only','Ontario_actual_and_mapping', ...
    'all_boundary_actual_only','combined'};
assert(any(strcmp(mode,modes)),'westernCorrection:Mode','Unknown western reconstruction mode.');
mpc=npcc_nygrid_2025_par_controlled_dc(hour_index,topology);
root=fileparts(fileparts(mfilename('fullpath')));
folder=fullfile(root,'output','nygrid_2025_western_audit');

function mpc = npcc_nygrid_2025_line_estimated_dc(hour_index, topology, scenario)
%NPCC_NYGRID_2025_LINE_ESTIMATED_DC Source-informed project parameter scenario.
% F84 uses a project-design Mallard ACSS/geometry estimate; Staten uses its
