function result = npcc_nygrid_2025_slim_interfaces(solved_case)
%NPCC_NYGRID_2025_SLIM_INTERFACES Recover the comparable legacy flow functionals.
% Values are modelMW; public-equivalentMW divides by the frozen gamma.
assert(isstruct(solved_case)&&isfield(solved_case,'success')&&solved_case.success, ...
    'nygridSlim:UnsolvedCase','Pass a successful rundcpf result.');
assert(isfield(solved_case,'userdata')&&isfield(solved_case.userdata,'slim'), ...
    'nygridSlim:MissingRecovery','Use the slim-case loader first.');
meta=solved_case.userdata.slim;
assert(isequal(solved_case.bus(:,1),meta.bus_ids),'nygridSlim:BusOrder','Solved bus order differs from recovery metadata.');
flow=meta.interface_angle_matrix*deg2rad(solved_case.bus(:,9))+meta.interface_flow_offset(:);
result=table(string(meta.interface_names(:)),flow,flow/meta.gamma, ...
    'VariableNames',{'interface','model_mw','public_equivalent_mw'});
end

function mpc = npcc_nygrid_2025_ac(hour_index)
%NPCC_NYGRID_2025_AC Full synthetic AC case on unchanged model power base.
% Engineering study assumptions, not an as-built or historical AC replay.
% All hourly native active-power boxes and six prescribed transfers survive.
% Native Q boxes use hourly admitted capability at assumed0.95PF; external
% boundary equivalents use fixed-P circle slices at finite declared MVA.
% Costs penalize departure from the DC prior and Q use; they are not economic.
% Default hour8508 is a tested post-Dover snapshot; qualification is per hour.
if nargin<1,hour_index=8508;end
root=fileparts(fileparts(mfilename('fullpath')));
prior=npcc_nygrid_2025_dover_dc(hour_index,'bounded','x_nominal');
mpc=prior;
if prior.userdata.dover.new_parameters_applied
    n=load(fullfile(root,'output','nygrid_2025_dover_parameters','network','x_nominal.mat'));
    c=n.full_case;c.branch(411:412,10)=prior.userdata.dover.bank_shift_model_deg;
else
    n=load(fullfile(root,'output','nygrid_2025_line_parameters','overlays','engineering_nominal','full191_network_cases.mat'));
    c=n.(prior.userdata.slim.network_state);

function [result,audit]=run_nygrid_2025_ac_dlr(hour_index,weather,options)
%RUN_NYGRID_2025_AC_DLR Whole-system synthetic ACOPF with OH current limits.
% Applies every active overhead segment's weather-dependent steady ampacity.
% Cables, transformers, PARs and terminal equipment keep separate MVA limits.
% This snapshot uses declared reference-temperature R, not an inferred
% equilibrium conductor temperature or an observed historical-weather replay.
if nargin<1,hour_index=8508;end
if nargin<2||isempty(weather)
    weather=table(25,.6096,90,1000,101325,'VariableNames', ...
        {'ambient_c','wind_m_s','wind_angle_deg','solar_w_m2','pressure_pa'});
end
if isstruct(weather),weather=struct2table(weather);end
if nargin<3,options=struct();end
if ~isfield(options,'solver')
    if exist('ipopt','file')==3,options.solver='IPOPT';else,options.solver='MIPS';end
end
root=fileparts(fileparts(mfilename('fullpath')));
addpath(fullfile(root,'scripts','nygrid_2025_ac_system','thermal'));

function model=npcc_nygrid_2025_compact_ac(hour_index)
%NPCC_NYGRID_2025_COMPACT_AC Compact AC admittance model anchored to148 buses.
% Use run_nygrid_2025_compact_acpf(model), not runpf(model): equivalent
% matrix couplings are not physical conductor branches. Detailed currents
% and eliminated voltages are recovered algebraically from the148-bus solve.
if nargin<1,hour_index=8508;end
root=fileparts(fileparts(mfilename('fullpath')));
addpath(fullfile(root,'scripts','nygrid_2025_compact_ac','core'));
model=compact_ac_build(npcc_nygrid_2025_ac(hour_index));
end

function [result,audit,recovered]=run_nygrid_2025_compact_acpf(input,mpopt)
%RUN_NYGRID_2025_COMPACT_ACPF Solve the148-bus complex AC equivalent.
% INPUT is an hour index, a compact_ac_build model, or a detailed MATPOWER
% case to reduce. RESULT.bus contains only retained nodes. RECOVERED is the
% algebraically recovered detailed MATPOWER result, including line powers.
% No OPF is used. Convergence and physical operating qualification differ.
if nargin<1||isempty(input),input=8508;end
if nargin<2,mpopt=[];end
root=fileparts(fileparts(mfilename('fullpath')));
addpath(fullfile(root,'scripts','nygrid_2025_compact_ac','core'));
if isnumeric(input)
    c=npcc_nygrid_2025_compact_ac(input);
elseif isfield(input,'model_kind')&&strcmp(input.model_kind,'compact_complex_admittance_AC')
    c=input;
else
    c=compact_ac_build(input);
end
[result,audit,recovered]=compact_ac_solve(c,mpopt);

function [result,audit,recovered,allocation]=run_nygrid_2025_loss_consistent_acpf(input,options)
%RUN_NYGRID_2025_LOSS_CONSISTENT_ACPF Versioned148-bus loss-accounting replay.
% INPUT is a2025hour or unrevised detailed NYGRID case. This is PF-only.
% Default: published E-G network equivalent and boundary-consistent losses.
if nargin<1||isempty(input),input=8508;end
if nargin<2,options=struct();end
if ~isfield(options,'impedance_mode'),options.impedance_mode='released_equivalent';end
root=fileparts(fileparts(mfilename('fullpath')));
addpath(fullfile(root,'scripts','nygrid_2025_ac_loss_revision','core'));
if isnumeric(input),m=npcc_nygrid_2025_ac(input);else,m=input;end
m=ac_loss_prepare_case(m,options.impedance_mode);
if isfield(options,'loss_mode')&&strcmp(options.loss_mode,'legacy_single_slack')
    [result,audit,recovered,allocation]=ac_loss_solve(m,options);
elseif isfield(options,'loss_solver')&&strcmp(options.loss_solver,'outer_fixed_point')
    [result,audit,recovered,allocation]=ac_loss_solve(m,options);
else
    [result,audit,recovered,allocation]=ac_loss_coupled_solve(m,options);
end

